from pathlib import Path

p = Path('sethiportfolio.html')
s = p.read_text(encoding='utf-8')

old_controls = '''                        <div class="flex flex-wrap items-center gap-2">\n                            <div class="flex rounded-lg bg-gray-100 p-1 text-xs font-black">\n                                <button onclick="setRange('1M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1M</button>\n                                <button onclick="setRange('3M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">3M</button>\n                                <button onclick="setRange('YTD', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">YTD</button>\n                                <button onclick="setRange('1Y', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1Y</button>\n                                <button onclick="setRange('SI', this)" class="range-btn px-3 py-1.5 rounded-md bg-white text-blue-700 shadow-sm">Since Inception</button>\n                            </div>\n                        </div>\n                    </div>\n                    <div class="flex flex-wrap gap-2 mb-1">\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-blue-50 text-blue-700 border border-blue-200 text-xs font-black" data-series="portfolio">● Sethi Portfolio</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="sp500">● S&amp;P 500</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="nasdaq">● Nasdaq-100</button>\n                        <button class="benchmark-toggle px-3 py-1.5 rounded-full bg-gray-50 text-gray-700 border border-gray-200 text-xs font-black" data-series="vwrl">● VWRL</button>\n                    </div>\n                    <div id="performance-chart" style="height:330px"></div>'''

new_controls = '''                        <div class="flex flex-wrap items-center gap-2">\n                            <div class="flex rounded-lg bg-gray-100 p-1 text-xs font-black">\n                                <button onclick="setRange('1M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1M</button>\n                                <button onclick="setRange('3M', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">3M</button>\n                                <button onclick="setRange('YTD', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">YTD</button>\n                                <button onclick="setRange('1Y', this)" class="range-btn px-3 py-1.5 rounded-md text-gray-500">1Y</button>\n                                <button onclick="setRange('SI', this)" class="range-btn px-3 py-1.5 rounded-md bg-white text-blue-700 shadow-sm">Since Inception</button>\n                            </div>\n                            <div class="relative">\n                                <button id="series-menu-btn" type="button" onclick="toggleSeriesMenu()" class="flex items-center gap-2 px-3 py-2 rounded-lg border border-gray-200 bg-white text-xs font-black text-gray-700 hover:bg-gray-50 transition shadow-sm">\n                                    Series <span id="series-count" class="text-blue-700">4/4</span> <span class="text-gray-400">▾</span>\n                                </button>\n                                <div id="series-menu" class="hidden absolute right-0 mt-2 w-48 bg-white border border-gray-200 rounded-xl shadow-lg p-2 z-30">\n                                    <label class="flex items-center gap-2 px-2 py-2 text-xs font-bold text-gray-700"><input type="checkbox" checked disabled class="accent-blue-600"> Sethi Portfolio</label>\n                                    <label class="flex items-center gap-2 px-2 py-2 text-xs font-bold text-gray-700 hover:bg-gray-50 rounded-lg cursor-pointer"><input type="checkbox" checked data-series-check="sp500" class="accent-blue-600"> S&amp;P 500</label>\n                                    <label class="flex items-center gap-2 px-2 py-2 text-xs font-bold text-gray-700 hover:bg-gray-50 rounded-lg cursor-pointer"><input type="checkbox" checked data-series-check="nasdaq" class="accent-blue-600"> Nasdaq-100</label>\n                                    <label class="flex items-center gap-2 px-2 py-2 text-xs font-bold text-gray-700 hover:bg-gray-50 rounded-lg cursor-pointer"><input type="checkbox" checked data-series-check="vwrl" class="accent-blue-600"> VWRL</label>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                    <div id="performance-chart" style="height:365px"></div>'''

if old_controls not in s:
    raise SystemExit('Benchmark control block not found')
s = s.replace(old_controls, new_controls, 1)

old_js = '''    document.querySelectorAll('.benchmark-toggle').forEach(btn => btn.addEventListener('click', () => {\n        const k = btn.dataset.series;\n        if (k === 'portfolio') return;\n        activeSeries[k] = !activeSeries[k];\n        btn.classList.toggle('opacity-40', !activeSeries[k]);\n        renderPerformance();\n    }));'''

new_js = '''    function toggleSeriesMenu() {\n        document.getElementById('series-menu').classList.toggle('hidden');\n    }\n\n    function updateSeriesCount() {\n        const activeCount = 1 + ['sp500', 'nasdaq', 'vwrl'].filter(k => activeSeries[k]).length;\n        document.getElementById('series-count').textContent = `${activeCount}/4`;\n    }\n\n    document.querySelectorAll('[data-series-check]').forEach(input => input.addEventListener('change', () => {\n        const k = input.dataset.seriesCheck;\n        activeSeries[k] = input.checked;\n        updateSeriesCount();\n        renderPerformance();\n    }));\n\n    document.addEventListener('click', (event) => {\n        const menu = document.getElementById('series-menu');\n        const button = document.getElementById('series-menu-btn');\n        if (!menu.contains(event.target) && !button.contains(event.target)) menu.classList.add('hidden');\n    });'''

if old_js not in s:
    raise SystemExit('Benchmark toggle JS block not found')
s = s.replace(old_js, new_js, 1)

p.write_text(s, encoding='utf-8')
